drafts.2:
h1 {
  text-align: center;
  font-size: 32px;
  color: #4338ca;
}
p { text-align: center; }

drafts.4:
 ul {
  display: flex;
  gap: 20px;
  list-style: none;
  padding: 0;
}
a { color: #4338ca; text-decoration: none; }
a:hover { text-decoration: underline; }

drafts.5:
table { width: 100%; border-collapse: collapse; }
th, td { border: 1px solid #94a3b8; padding: 8px; text-align: left; }
th { background-color: #bfdbfe; }

drafts.6:
form { background: #f1f5f9; padding: 16px; border-radius: 10px; }
label { display: block; margin: 10px 0 4px; }
input { width: 100%; padding: 8px; margin-bottom: 8px; border: 1px solid #94a3b8; border-radius: 5px; }
button { padding: 9px 14px; background: #4f46e5; color: white; border: 0; border-radius: 5px; }

drafts.7:
.card {
  max-width: 360px;
  margin: 20px auto;
  padding: 18px;
  background: white;
  border: 1px solid #cbd5e1;
  border-radius: 12px;
  box-shadow: 0 4px 12px #0f172a18;
}
.card h2 { color: #3730a3; margin-top: 0; }
.card a { color: #4f46e5; }
